#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using Kamilunavo.OneMoreFloor.Visuals;
using Kamilunavo.OneMoreFloor.UI;
using Kamilunavo.OneMoreFloor.CameraSystem;

// Structural presentation regression. Actual concept fidelity and mobile cost need rendered/device evidence.
public static class FloorGraphicsRefinementValidation
{
 static int checks;
 static void Check(bool condition,string message){checks++;if(!condition)throw new InvalidOperationException("FLOOR_GRAPHICS: "+message);}
 public static void Validate(){checks=0;var errors=new List<string>();Application.LogCallback capture=(message,trace,type)=>{if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors.Add(message);};Application.logMessageReceived+=capture;try{Cabin();City();Previews();Framing();foreach(var name in new[]{"FloorArchitecturalMetal","FloorMasonry","FloorCabinGlass"}){var shader=Resources.Load<Shader>(name);Check(shader!=null&&!ShaderUtil.ShaderHasError(shader),"shipping shader imported without compiler errors: "+name);}Check(errors.Count==0,"no logged errors during creation/teardown: "+string.Join(" | ",errors));Debug.Log("FLOOR_GRAPHICS_REFINEMENT_PASS checks="+checks+" renderedConceptReview=PENDING");}finally{Application.logMessageReceived-=capture;}}
 static void Cabin(){var host=new GameObject("GraphicsCabinFixture");var owned=new HashSet<UnityEngine.Object>();try{PlatformArt.Build(host.transform,0,0);var cabin=host.transform.Find("CopperLiftCabin");var glass=cabin.Find("CabinSideAndRearGlass");Check(glass!=null,"real rear/side glazing exists");var mesh=glass.GetComponent<MeshFilter>().sharedMesh;Check(mesh.vertexCount==12&&mesh.triangles.Length==18,"three clear glass panels form one bounded draw surface");foreach(var vertex in mesh.vertices)Check(vertex.z>=-.131f,"front transfer opening is free of a glazing plane");var material=glass.GetComponent<Renderer>().sharedMaterial;Check(material.shader.name=="Floor/CabinGlass"&&material.color.a<=.10f&&material.renderQueue>=3000,"glass is transparent and leaves the runner readable");foreach(var name in new[]{"CabinBaseDrum","CabinCrown"}){var filter=cabin.Find(name).GetComponent<MeshFilter>();Check(filter.sharedMesh.vertexCount>=450,"substantial multi-band shaped carriage: "+name);Check(filter.GetComponent<Renderer>().sharedMaterial.shader.name=="Floor/ArchitecturalMetal","view-dependent authored brass finish: "+name);}
 var collider=host.transform.Find("LandingSurface").GetComponent<BoxCollider>();Check(collider!=null&&host.GetComponentsInChildren<Collider>(true).Length==1&&collider.center==new Vector3(0,.25f,0)&&collider.size==new Vector3(4.6f,.70f,3.6f),"exact original authoritative landing collider retained");int vertices=0;foreach(var filter in host.GetComponentsInChildren<MeshFilter>(true)){vertices+=filter.sharedMesh.vertexCount;Check(filter.sharedMesh.bounds.size.sqrMagnitude>0,"nonempty geometry");}Check(vertices<30000,"one platform kit remains within its existing geometry budget");Collect(host,owned);Debug.Log("FLOOR_GRAPHICS_PLATFORM_BUDGET vertices="+vertices);UnityEngine.Object.DestroyImmediate(host);Disposed(owned);}finally{if(host!=null)UnityEngine.Object.DestroyImmediate(host);}}
 static void City(){var host=new GameObject("GraphicsCityFixture");var owned=new HashSet<UnityEngine.Object>();var sky=RenderSettings.skybox;var mode=RenderSettings.ambientMode;var skyColor=RenderSettings.ambientSkyColor;var equator=RenderSettings.ambientEquatorColor;var ground=RenderSettings.ambientGroundColor;bool fog=RenderSettings.fog;var fogMode=RenderSettings.fogMode;var fogColor=RenderSettings.fogColor;float density=RenderSettings.fogDensity;try{CityArt.Build(host.transform);int chambers=0,facades=0;var meshes=new HashSet<Mesh>();var materials=new HashSet<Material>();var textures=new HashSet<Texture>();foreach(var node in host.GetComponentsInChildren<Transform>()){if(node.name=="HistoricBellChamber"){Check(node.position.y+9.6f<0,"distant bell chamber ends below the initial landing instead of masking the sky");chambers++;Check(node.Find("BellTowerCopperSpire")!=null&&node.Find("BellChamberCornice")!=null,"distant city silhouette has open bell-chamber architecture");}if(node.name=="GroundedFacade"){facades++;Check(node.parent.Find("QuayMasonryPlinth")!=null,"facades meet the canal with a substantial masonry footing");Check(node.parent.localPosition.z>=200||Mathf.Abs(node.parent.localPosition.x)>24,"city leaves the existing route corridor clear");}}foreach(var filter in host.GetComponentsInChildren<MeshFilter>())meshes.Add(filter.sharedMesh);foreach(var renderer in host.GetComponentsInChildren<MeshRenderer>()){materials.Add(renderer.sharedMaterial);if(renderer.sharedMaterial.mainTexture!=null)textures.Add(renderer.sharedMaterial.mainTexture);}int vertices=0;foreach(var mesh in meshes)vertices+=mesh.vertexCount;Check(chambers==12&&facades==45,"all authored quarters retain their original city positions and refined rooflines");Check(vertices<250000&&materials.Count<=12&&textures.Count<=2,"complete city geometry and finish memory remain bounded");Check(host.GetComponentsInChildren<Collider>().Length==0&&host.GetComponentsInChildren<Light>().Length==0,"decorative city adds no physics or real-time light");Collect(host,owned);Debug.Log("FLOOR_GRAPHICS_CITY_BUDGET uniqueMeshVertices="+vertices+" materials="+materials.Count+" textures="+textures.Count);UnityEngine.Object.DestroyImmediate(host);Disposed(owned);}finally{RenderSettings.skybox=sky;RenderSettings.ambientMode=mode;RenderSettings.ambientSkyColor=skyColor;RenderSettings.ambientEquatorColor=equator;RenderSettings.ambientGroundColor=ground;RenderSettings.fog=fog;RenderSettings.fogMode=fogMode;RenderSettings.fogColor=fogColor;RenderSettings.fogDensity=density;if(host!=null)UnityEngine.Object.DestroyImmediate(host);}}
 static void Previews(){var host=new GameObject("GraphicsPreviewFixture",typeof(RectTransform));try{var colors=new HashSet<Color>();var signatures=new HashSet<string>();for(int chapter=0;chapter<3;chapter++){var rect=LiftScenePreview.CreateCity(host.transform,chapter);var scene=rect.GetComponent<LiftScenePreview>().SceneRoot;var owned=new HashSet<UnityEngine.Object>();var materials=new HashSet<Material>();var textures=new HashSet<Texture>();int vertices=0,arches=0,bevels=0;var shape=new List<string>();foreach(var filter in scene.GetComponentsInChildren<MeshFilter>()){vertices+=filter.sharedMesh.vertexCount;if(filter.name=="WindowArch")arches++;if(filter.name=="MasonryBlock"){bevels++;Check(filter.sharedMesh.vertexCount>=128,"chapter masonry has actual clipped corners");shape.Add(filter.sharedMesh.bounds.size.ToString("R"));}}foreach(var renderer in scene.GetComponentsInChildren<MeshRenderer>()){var material=renderer.sharedMaterial;materials.Add(material);if(material.mainTexture!=null)textures.Add(material.mainTexture);if(material.name.StartsWith("LobbyCityStone",StringComparison.Ordinal))colors.Add(material.color);}shape.Sort();signatures.Add(string.Join(";",shape));Check(arches>=60&&bevels>=2,"each chapter includes recessed arched window architecture");Check(vertices<35000&&materials.Count<=10&&textures.Count<=2,"chapter preview has bounded mobile geometry/material/texture cost");Check(scene.GetComponentsInChildren<Collider>().Length==0,"menu scenery cannot affect collision");var camera=scene.GetComponentInChildren<Camera>();Check(camera.cullingMask==(1<<LiftScenePreview.PreviewLayer)&&camera.farClipPlane<=40,"preview camera remains isolated and bounded");Collect(scene,owned);Debug.Log("FLOOR_GRAPHICS_PREVIEW_BUDGET chapter="+chapter+" vertices="+vertices+" materials="+materials.Count);UnityEngine.Object.DestroyImmediate(rect.gameObject);Disposed(owned);}Check(colors.Count==3&&signatures.Count==3,"all three chapter palettes and authored masonry silhouettes remain distinct");Check(LiftScenePreview.CabinPreviewSize(.55f)<3.0f&&LiftScenePreview.CabinPreviewSize(1.6f)<3.0f,"lobby lift and runner occupy a useful portrait/landscape hero area");}finally{UnityEngine.Object.DestroyImmediate(host);}}
 static void Framing(){var rotation=Quaternion.Euler(27,-18,0);var source=Vector3.up*.65f;foreach(float aspect in new[]{.46f,.5625f,1.77778f})foreach(var view in new[]{new Rect(.08f,.23f,.84f,.54f),new Rect(.08f,.43f,.84f,.34f),new Rect(.08f,.58f,.84f,.19f)})foreach(float offset in new[]{-2.2f,0,2.2f}){var next=new Vector3(offset,2.35f,3.7f);var head=source+Vector3.up*2.5f;var focus=OrbitCamera.BestFocus(rotation,60,aspect,source,next,head,view);float distance=OrbitCamera.FitDistance(focus,rotation,60,aspect,source,next,head,view),old=OrbitCamera.FitDistance((source+next)*.5f+Vector3.up*.8f,rotation,60,aspect,source,next,head,view);Check(distance<=old+.0001f,"closer framing never exceeds the original fit distance");float tangent=Mathf.Tan(30*Mathf.Deg2Rad);var eye=focus+rotation*Vector3.up*(distance*tangent*(1-2*view.center.y))-rotation*Vector3.forward*distance;void Visible(Vector3 point){var local=Quaternion.Inverse(rotation)*(point-eye);float x=.5f+local.x/(local.z*tangent*aspect)*.5f,y=.5f+local.y/(local.z*tangent)*.5f;Check(local.z>0&&x>=view.xMin&&x<=view.xMax&&y>=view.yMin&&y<=view.yMax,"complete current/next landing footprint and runner/arc stay within reserved gameplay viewport");}foreach(var center in new[]{source,next}){for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Visible(center+new Vector3(x*2.4f,0,z*1.9f));for(int side=-1;side<=1;side+=2)Visible(center+new Vector3(side*1.18f,3.35f,1.1f));}Visible(head);Visible((source+next)*.5f+Vector3.up*2.2f);}}
 static void Collect(GameObject host,HashSet<UnityEngine.Object> owned){foreach(var filter in host.GetComponentsInChildren<MeshFilter>(true))owned.Add(filter.sharedMesh);foreach(var renderer in host.GetComponentsInChildren<MeshRenderer>(true)){var material=renderer.sharedMaterial;if(material.name.StartsWith("FloorArchitecture",StringComparison.Ordinal)||material.name.StartsWith("LobbyCity",StringComparison.Ordinal)&&!material.name.StartsWith("LobbyCityGlass",StringComparison.Ordinal)){owned.Add(material);if(material.mainTexture!=null)owned.Add(material.mainTexture);}}}
 static void Disposed(HashSet<UnityEngine.Object> owned){foreach(var asset in owned)Check(asset==null,"owned generated geometry/finish resources released on whole-host teardown");}
}
#endif
